 { t: "esle", ar: "التَّدْريبُ (٢): صِلْ بَيْنَ الكَلِمَةِ وَالتَّعْريفِ المُناسِبِ", ciftler: [
  ["الشَّبابُ", "المَرْحَلَةُ مِنَ العُمُرِ بَعْدَ الطُّفولَةِ.", "gençlik"], ["المُهاجِرونَ", "الَّذينَ هاجَروا مِنْ مَكَّةَ إِلى المَدينَةِ.", "muhacirler"], ["الغَزْوَةُ", "الحَرْبُ بَيْنَ جَيْشَيْنِ وَفيها رَسولُ اللهِ ﷺ.", "gazve"], ["الكَسْلانُ", "الَّذي لا يُحِبُّ العَمَلَ.", "tembel"], ["الأَنْصارُ", "أَهْلُ المَدينَةِ الَّذينَ آمَنوا بِمُحَمَّدٍ ﷺ.", "ensar"]] }
